#ifndef M9_FAA_GRAPH_DUAL_LATER_ENCODE_H
#define M9_FAA_GRAPH_DUAL_LATER_ENCODE_H

#include "m9_faa_graph_dual_first_encode.h"
#include "m9_faa_graph_later_depth_two_encode.h"
#include "m9_faa_graph_later_stage.h"

/* A retained, same-program dual-texture DRAW after an authenticated Unlock.
 * fresh_secondary and fresh_tail are independently generated by the live
 * FIRST dual producer for this job and texture pair. Their epoch is previous
 * Unlock for CLEAR3, or previous Unlock - 0x80 for no-clear. The first
 * producer owns all program, constant, vertex and sampler address joins.
 * No captured address or source allocation parameter enters this interface.
 * Output is CPU scratch; the caller authenticates/retains both texture owners
 * and publishes the returned ENDs only after all prior owners are fenced. */
#define M9_FAA_DUAL_LATER_SECONDARY_CLEAR 2736u
#define M9_FAA_DUAL_LATER_SECONDARY_NOCLEAR 2740u
#define M9_FAA_DUAL_LATER_TAIL_CLEAR 3632u
#define M9_FAA_DUAL_LATER_TAIL_NOCLEAR 3624u
#define M9_FAA_DUAL_LATER_CULL_BYTES 24u

struct m9x_faa_dual_later_image {
	u8 *primary, *secondary;
	u32 primary_capacity, secondary_capacity;
	u32 primary_bytes, secondary_bytes;
	u32 end_bytes[13], end_count, clear_bytes, draw_end_bytes;
	/* Sampler 0x70 header offsets in the secondary. */
	u32 units, site[2];
	u64 final_point;
};

struct m9x_faa_dual_later_scratch {
	struct m9x_faa_later_depth_scratch clear;
	u8 primary[M9_FAA_LATER_DEPTH_PREFIX_CAPACITY + M9_FAA_DUAL_LATER_TAIL_CLEAR];
	/* Also holds a switched stage (FIRST + reload + E3). */
	u8 secondary[M9_FAA_SWITCH_STAGE_MAX];
};

int m9x_faa_dual_later_encode(const u8 *sample, size_t sample_bytes,
 const struct m9x_faa_graph_draw_owner owner[34],
 const struct m9x_faa_depth_views *views,
 u32 primary_cursor, u32 secondary_cursor, u64 previous_unlock,
 u64 live_next, u32 clear_flags,
 const u8 fresh_secondary[M9_FAA_DUAL_FIRST_SECONDARY_BYTES],
 const u8 fresh_tail[M9_FAA_DUAL_FIRST_PRIMARY_TAIL_BYTES],
 struct m9x_faa_dual_later_image *out,
 struct m9x_faa_dual_later_scratch *scratch);

/* First later DRAW in its program cache form: fresh_first is the DRAW
 * program's live FIRST stage (single 2720 or dual 2880 bytes) and tail,
 * encoded at the frame epoch. cull_state keeps the 6A cull groups.
 */
int m9x_faa_later_encode(const u8 *sample, size_t sample_bytes,
			 const struct m9x_faa_graph_draw_owner owner[34],
			 const struct m9x_faa_depth_views *views,
			 u32 primary_cursor, u32 secondary_cursor,
			 u64 previous_unlock, u64 live_next, u32 clear_flags,
			 const u8 *fresh_first, u32 fresh_first_bytes,
			 const u8 fresh_tail[M9_FAA_DUAL_FIRST_PRIMARY_TAIL_BYTES],
			 enum m9x_faa_later_form form, bool cull_state,
			 struct m9x_faa_dual_later_image *out,
			 struct m9x_faa_dual_later_scratch *scratch);

#endif
